import{_ as p,a0 as l,w as r,s as o,ao as d,I as t,x as n,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"用 ranger 在 Linux 文件的海洋中導航 | LCTT x X-CMD","titleTemplate":false,"description":"用 ranger 在 Linux 文件的海洋中導航 | LCTT (202102) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 ranger 在 Linux 文件的海洋中導航 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 ranger 在 Linux 文件的海洋中導航 | LCTT (202102) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202102/20201001 Navigating your Linux files with ranger","title":"用 ranger 在 Linux 文件的海洋中導航","tag":"202102","desc":""},"relativePath":"202102/20201001 Navigating your Linux files with ranger.md","filePath":"[post].md"}'),c={name:"202102/20201001 Navigating your Linux files with ranger.md"};function g(h,s,u,k,f,b){const a=l("Link");return r(),o("div",null,[s[15]||(s[15]=d(`<h1 id="用-ranger-在-linux-文件的海洋中導航" tabindex="-1">用 ranger 在 Linux 文件的海洋中導航 <a class="header-anchor" href="#用-ranger-在-linux-文件的海洋中導航" aria-label="Permalink to “用 ranger 在 Linux 文件的海洋中導航”">​</a></h1><blockquote><p>ranger 是一個很好的工具，它為你的 Linux 文件提供了一個多級視圖，並允許你使用方向鍵和一些方便的命令進行瀏覽和更改。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202102/20/121918g5hqhjfcjyffh3lt.jpg" alt=""></p><p><code>ranger</code> 是一款獨特且非常方便的文件系統導航器，它允許你在 Linux 文件系統中移動，進出子目錄，查看文本文件內容，甚至可以在不離開該工具的情況下對文件進行修改。</p><p>它運行在終端窗口中，並允許你按下方向鍵進行導航。它提供了一個多級的文件顯示，讓你很容易看到你在哪裏、在文件系統中移動、並選擇特定的文件。</p><p>要安裝 <code>ranger</code>，請使用標準的安裝命令（例如，<code>sudo apt install ranger</code>）。要啓動它，只需鍵入 <code>ranger</code>。它有一個很長的、非常詳細的手冊頁面，但開始使用 <code>ranger</code> 非常簡單。</p><h3 id="ranger-的顯示方式" tabindex="-1">ranger 的顯示方式 <a class="header-anchor" href="#ranger-的顯示方式" aria-label="Permalink to “ranger 的顯示方式”">​</a></h3><p>你需要馬上習慣的最重要的一件事就是 <code>ranger</code> 的文件顯示方式。一旦你啓動了 <code>ranger</code>，你會看到四列數據。第一列是你啓動 <code>ranger</code> 的位置的上一級。例如，如果你從主目錄開始，<code>ranger</code> 將在第一列中列出所有的主目錄。第二列將顯示你的主目錄（或者你開始的目錄）中的目錄和文件的第一屏內容。</p><p>這裏的關鍵是超越你可能有的任何習慣，將每一行顯示的細節看作是相關的。第二列中的所有條目與第一列中的單個條目相關，第四列中的內容與第二列中選定的文件或目錄相關。</p><p>與一般的命令列視圖不同的是，目錄將被列在第一位（按字母數字順序），文件將被列在第二位（也是按字母數字順序）。從你的主目錄開始，顯示的內容可能是這樣的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>shs@dragonfly /home/shs/backups     &lt;== current selection</span></span>
<span class="line"><span> bugfarm   backups            0  empty</span></span>
<span class="line"><span> dory      bin               59</span></span>
<span class="line"><span> eel       Buttons           15</span></span>
<span class="line"><span> nemo      Desktop            0</span></span>
<span class="line"><span> shark     Documents          0</span></span>
<span class="line"><span> shs       Downloads          1</span></span>
<span class="line"><span>   ^         ^                ^      ^</span></span>
<span class="line"><span>   |         |                |      |</span></span>
<span class="line"><span> homes     directories    # files    listing</span></span>
<span class="line"><span>           in selected    in each    of files in</span></span>
<span class="line"><span>           home           directory  selected directory</span></span></code></pre></div><p><code>ranger</code> 顯示的最上面一行告訴你在哪裏。在這個例子中，當前目錄是 <code>/home/shs/backups</code>。我們看到高亮顯示的是 <code>empty</code>，因為這個目錄中沒有文件。如果我們按下方向鍵選擇 <code>bin</code>，我們會看到一個文件列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>shs@dragonfly /home/shs/bin      &lt;== current selection</span></span>
<span class="line"><span> bugfarm   backups            0    append</span></span>
<span class="line"><span> dory      bin               59    calcPower</span></span>
<span class="line"><span> eel       Buttons           15    cap</span></span>
<span class="line"><span> nemo      Desktop            0    extract</span></span>
<span class="line"><span> shark     Documents          0    finddups</span></span>
<span class="line"><span> shs       Downloads          1    fix</span></span>
<span class="line"><span>   ^         ^                ^      ^</span></span>
<span class="line"><span>   |         |                |      |</span></span>
<span class="line"><span> homes     directories    # files    listing</span></span>
<span class="line"><span>           in selected    in each    of files in</span></span>
<span class="line"><span>           home           directory  selected directory</span></span></code></pre></div><p>每一列中高亮顯示的條目顯示了當前的選擇。使用右方向鍵可移動到更深的目錄或查看文件內容。</p><p>如果你繼續按下方向鍵移動到列表的文件部分，你會注意到第三列將顯示文件大小（而不是文件的數量）。“當前選擇”行也會顯示當前選擇的文件名，而最右邊的一列則會盡可能地顯示文件內容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>shs@dragonfly /home/shs/busy_wait.c   &lt;== current selection</span></span>
<span class="line"><span> bugfarm   BushyRidge.zip    170 K  /*</span></span>
<span class="line"><span> dory      busy_wait.c       338 B   * program that does a busy wait</span></span>
<span class="line"><span> eel       camper.jpg       5.55 M   * it&#39;s used to show ASLR, and that&#39;s it</span></span>
<span class="line"><span> nemo      check_lockscreen   80 B   */</span></span>
<span class="line"><span> shark     chkrootkit-output 438 B  #include &lt;stdio.h&gt;</span></span>
<span class="line"><span>   ^         ^                ^       ^</span></span>
<span class="line"><span>   |         |                |       |</span></span>
<span class="line"><span> homes     files            sizes    file content</span></span></code></pre></div><p>在該顯示的底行會顯示一些文件和目錄的詳細信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>-rw-rw-r—- shs shs 338B 2019-01-05 14:44    1.52G, 365G free  67/488  11%</span></span></code></pre></div><p>如果你選擇了一個目錄並按下回車鍵，你將進入該目錄。然後，在你的顯示屏中最左邊的一列將是你的主目錄的內容列表，第二列將是該目錄內容的文件列表。然後你可以檢查子目錄的內容和文件的內容。</p><p>按左方向鍵可以向上移動一級。</p><p>按 <code>q</code> 鍵退出 <code>ranger</code>。</p><h3 id="做出改變" tabindex="-1">做出改變 <a class="header-anchor" href="#做出改變" aria-label="Permalink to “做出改變”">​</a></h3><p>你可以按 <code>?</code> 鍵，在屏幕底部彈出一條幫助行。它看起來應該是這樣的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>View [m]an page, [k]ey bindings, [c]commands or [s]ettings?  (press q to abort)</span></span></code></pre></div><p>按 <code>c</code> 鍵，<code>ranger</code> 將提供你可以在該工具內使用的命令信息。例如，你可以通過輸入 <code>:chmod</code> 來改變當前文件的權限，後面跟着預期的權限。例如，一旦選擇了一個文件，你可以輸入 <code>:chmod 700</code> 將權限設置為 <code>rwx------</code>。</p><p>輸入 <code>:edit</code> 可以在 <code>nano</code> 中打開該文件，允許你進行修改，然後使用 <code>nano</code> 的命令保存文件。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>使用 <code>ranger</code> 的方法比本篇文章所描述的更多。該工具提供了一種非常不同的方式來列出 Linux 系統上的文件並與之交互，一旦你習慣了它的多級的目錄和文件列表方式，並使用方向鍵代替 <code>cd</code> 命令來移動，就可以很輕鬆地在 Linux 的文件中導航。</p><hr>`,29)),t("p",null,[s[1]||(s[1]=n("via: ",-1)),e(a,{href:"https://www.networkworld.com/article/3583890/navigating-your-linux-files-with-ranger.html"},{default:i(()=>[...s[0]||(s[0]=[n("https://www.networkworld.com/article/3583890/navigating-your-linux-files-with-ranger.html",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=n("作者：",-1)),e(a,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>[...s[2]||(s[2]=[n("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=n(" 選題：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[n("lujun9972",-1)])]),_:1}),s[8]||(s[8]=n(" 譯者：",-1)),e(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[4]||(s[4]=[n("wxy",-1)])]),_:1}),s[9]||(s[9]=n(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[n("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=n("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[n("LCTT",-1)])]),_:1}),s[13]||(s[13]=n(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[n("Linux中國",-1)])]),_:1}),s[14]||(s[14]=n(" 榮譽推出",-1))])])}const w=p(c,[["render",g]]);export{y as __pageData,w as default};
